// Nodo función "Guardar telemetría de zona" — entrada: ems/<edif>/zona/<Z>/telemetria
// Guarda el último valor por zona en el contexto del flujo para que la lógica EMS lo use.
const z = msg.payload;
if (!z || !z.zona) { return null; }
const zonas = flow.get("zonas") || {};
z._recibido = Date.now();
zonas[z.zona] = z;
flow.set("zonas", zonas);
return null;

// Nodo función "EMS: reglas + respuesta a la demanda" — entrada: ems/<edif>/medidor/general
// Misma lógica que ems/control.py (clase ReglasDR). Se ejecuta una vez por paso de simulación.
// Salida 1: comandos por zona (ems/<edif>/zona/<Z>/cmd)
// Salida 2: estado del EMS (ems/<edif>/ems/estado)
// Salida 3: alarmas (ems/<edif>/alarma)

const P = Object.assign({
    edificio: env.get("EMS_EDIFICIO") || "edificio1",
    banda: 0.5, sp_ocupado: 24.0, sp_desocupado: 27.0, sp_noche: 29.0,
    precool_min: 60, entrada: 7.0, salida: 18.0,
    lux_objetivo: 500, lux_artificial: 500,
    luces_desocupado: 0.0, equipos_desocupado: 0.1, retardo_vacancia_min: 15,
    limite_kw: 30, dr_hist_kw: 3, dr_luces: 0.7, dr_equipos: 0.85, dr_margen_confort: 0.75,
    confort_max: 26.0, confort_min: 21.0, alarma_servidor: 27.0,
    plr_min: 0.15, banda_prop: 2.0
}, flow.get("parametros") || {});

// Terminal VRF de cada zona: [capacidad total kW, COP estacional del sistema, ventilador kW].
// Lo genera nodered/build_flows.py desde config/edificio.yaml; se puede reemplazar con flow "parametros" → hvac.
const HVAC = P.hvac || /*@HVAC@*/{"Z01": [5.76, 1.72, 0.147], "Z02": [19.41, 1.72, 0.435], "Z03": [13.36, 1.72, 0.269], "Z04": [17.04, 2.08, 0.433], "Z05": [16.13, 2.08, 0.397], "Z06": [15.31, 2.08, 0.37], "Z07": [14.54, 2.08, 0.341], "Z08": [3.55, 2.08, 0.099], "Z09": [2.89, 3.08, 0.086], "Z10": [0.16, 1.72, 0.003]}/*@FIN@*/;
// capacidad pedida por el terminal (ley proporcional, igual que ems/edificio.py: fraccion_carga)
const fraccionCarga = (t, sp) => Math.min(1, Math.max(P.plr_min, (t - sp + P.banda) / P.banda_prop));

const tInicio = Date.now();
const med = msg.payload;
const zonas = flow.get("zonas") || {};
const st = flow.get("st") || { ultimoOcup: {}, hist: {}, cont: {}, activas: {}, drEtapa: 0, drCont: 0, cmdId: 0 };
const base = "ems/" + P.edificio;

// ---------------------------------------------------------------- tiempo local (Panamá, UTC-5)
const d = new Date(med.ts);
const loc = new Date(d.getTime() - 5 * 3600 * 1000);
const h = loc.getUTCHours() + loc.getUTCMinutes() / 60;
const dow = loc.getUTCDay();                // 0 = domingo
const laborable = dow >= 1 && dow <= 5;
const horarioLaboral = laborable && h >= P.entrada - 0.5 && h < P.salida + 0.5;
const precool = laborable && h >= P.entrada - P.precool_min / 60 && h < P.entrada;

const alarmas = [];
function cond(clave, activa, pasos) {
    st.cont[clave] = activa ? (st.cont[clave] || 0) + 1 : 0;
    if (st.cont[clave] >= (pasos || 1) && !st.activas[clave]) { st.activas[clave] = true; return true; }
    if (!activa) { delete st.activas[clave]; }
    return false;
}
function alarma(nivel, codigo, zona, mensaje, valor) {
    alarmas.push({ ts: med.ts, nivel, codigo, zona, mensaje, valor: valor === undefined ? null : valor, origen: "nodered" });
}

// ---------------------------------------------------------------- validación de sensores + alarmas
const invalidos = {};
for (const zid of Object.keys(zonas)) {
    const z = zonas[zid];
    const hs = st.hist[zid] = (st.hist[zid] || []).concat([z.temp_c]).slice(-6);
    let motivo = null;
    if (typeof z.temp_c !== "number" || !isFinite(z.temp_c) || z.temp_c < 5 || z.temp_c > 50) motivo = "SENSOR_FUERA_RANGO";
    else if (hs.length === 6 && Math.max(...hs) - Math.min(...hs) < 0.005) motivo = "SENSOR_CONGELADO";
    else if (hs.length >= 4) {
        let saltos = 0;
        for (let i = 1; i < hs.length; i++) if (Math.abs(hs[i] - hs[i - 1]) > 1.2) saltos++;
        if (saltos >= 3) motivo = "SENSOR_FUERA_RANGO";
    }
    if (motivo) invalidos[zid] = true;
    if (cond(zid + ":SENSOR", !!motivo)) alarma("crit", motivo, zid, `Sensor no confiable (${z.temp_c}) → modo seguro`, z.temp_c);
    if (motivo) continue;
    if (cond(zid + ":TEMP_ALTA", z.ocupado && z.temp_c > P.confort_max, 3))
        alarma("warn", "TEMP_ALTA", zid, `${z.temp_c.toFixed(1)} °C > ${P.confort_max} °C con ocupación`, z.temp_c);
    if (cond(zid + ":TEMP_BAJA", z.ocupado && z.temp_c < P.confort_min, 3))
        alarma("info", "TEMP_BAJA", zid, `${z.temp_c.toFixed(1)} °C < ${P.confort_min} °C con ocupación`, z.temp_c);
    if (z.tipo === "servidores" && cond(zid + ":SRV", z.temp_c > P.alarma_servidor, 2))
        alarma("crit", "SERVIDOR_TEMP", zid, `Cuarto de servidores a ${z.temp_c.toFixed(1)} °C`, z.temp_c);
    if (!z.critica && cond(zid + ":HVAC_SIN_OCUP", z.hvac_on && !z.ocupado, 12))
        alarma("info", "HVAC_ON_SIN_OCUPACION", zid, "HVAC encendido > 60 min sin ocupación");
}
if (cond("EDIF:PICO", med.demanda_15min_kw > P.limite_kw))
    alarma("warn", "PICO_DEMANDA", "EDIF", `Demanda 15 min ${med.demanda_15min_kw.toFixed(1)} kW > ${P.limite_kw} kW`, med.demanda_15min_kw);

// ---------------------------------------------------------------- reglas por zona
const cmds = {};
const tMs = d.getTime();
for (const zid of Object.keys(zonas)) {
    const z = zonas[zid];
    if (z.critica) continue;
    if (z.ocupado) st.ultimoOcup[zid] = tMs;
    const ocup = z.ocupado || (st.ultimoOcup[zid] !== undefined && tMs - st.ultimoOcup[zid] <= P.retardo_vacancia_min * 60000);
    let sp, en;
    if (ocup || precool) { sp = P.sp_ocupado; en = true; }
    else if (horarioLaboral) { sp = P.sp_desocupado; en = true; }
    else { sp = P.sp_noche; en = z.temp_c > P.sp_noche + P.banda; }
    let luces, equipos;
    if (ocup) {
        const luxDia = Math.max(z.lux - P.lux_artificial * z.luces_nivel, 0);
        luces = Math.min(Math.max((P.lux_objetivo - luxDia) / P.lux_artificial, 0.1), 1.0);
        luces = Math.round(Math.round(luces / 0.05) * 0.05 * 100) / 100;
        equipos = 1.0;
    } else { luces = P.luces_desocupado; equipos = P.equipos_desocupado; }
    let vent = "dcv";
    // protección por baja temperatura (losa al terreno a 18 °C en el modelo E+): ventilador con aire exterior
    if (z.temp_c < P.confort_min + 1.0) { en = true; vent = "fija"; }
    cmds[zid] = { hvac_enable: en, setpoint_c: sp, ventilacion: vent, luces_nivel: luces, equipos_nivel: equipos, hvac_mod: null };
}

// ---------------------------------------------------------------- overrides del operador (prioridad sobre las reglas)
const ovs = flow.get("overrides") || {};
const manual = {};
for (const zid of Object.keys(ovs)) {
    const o = ovs[zid];
    if (!o || o.hasta <= Date.now()) { delete ovs[zid]; continue; }
    if (!cmds[zid]) continue; // zonas críticas o sin telemetría
    manual[zid] = true;
    if (o.setpoint_c !== undefined) { cmds[zid].setpoint_c = o.setpoint_c; cmds[zid].hvac_enable = true; }
    if (o.hvac_enable !== undefined) cmds[zid].hvac_enable = o.hvac_enable;
    if (o.luces_nivel !== undefined) cmds[zid].luces_nivel = o.luces_nivel;
    if (o.equipos_nivel !== undefined) cmds[zid].equipos_nivel = o.equipos_nivel;
}
flow.set("overrides", ovs);

// ---------------------------------------------------------------- limitador de demanda (rotación de compresores)
let pCompActual = 0;
let reservado = 0;
const sol = [];
for (const zid of Object.keys(cmds)) {
    const z = zonas[zid], c = cmds[zid];
    if (invalidos[zid]) continue;
    const [cap, copN, fanKw] = HVAC[zid] || [20, 3.0, 0];
    const cop = Math.max(copN * (1 - 0.012 * (med.t_ext_c - 30)), 1);
    const fan = z.hvac_enable && (z.ocupado || z.hvac_on) ? fanKw : 0;
    if (z.hvac_on) pCompActual += Math.max(z.p_hvac_kw - fan, 0);
    if (!c.hvac_enable) continue;
    const pideManual = z.temp_c > c.setpoint_c + P.banda || (z.hvac_on && z.temp_c > c.setpoint_c - P.banda);
    if (manual[zid]) { if (pideManual) reservado += fraccionCarga(z.temp_c, c.setpoint_c) * cap / cop; continue; } // el operador manda
    const pide = z.temp_c > c.setpoint_c + P.banda || (z.hvac_on && z.temp_c > c.setpoint_c - P.banda);
    if (pide) sol.push({ zid, urg: z.temp_c - c.setpoint_c, kw: fraccionCarga(z.temp_c, c.setpoint_c) * cap / cop, emerg: z.temp_c > P.confort_max - P.dr_margen_confort });
}
let presupuesto = P.limite_kw - 3 - (med.p_total_kw - pCompActual) - reservado;
let forzadas = 0;
sol.sort((a, b) => (a.emerg === b.emerg ? b.urg - a.urg : (a.emerg ? -1 : 1)));
for (const s of sol) {
    if (s.emerg || s.kw <= presupuesto) { presupuesto -= s.kw; continue; }
    cmds[s.zid].hvac_mod = 0.0;
    forzadas++;
}
const dem = med.demanda_15min_kw;
if (dem > P.limite_kw) { st.drEtapa = 2; st.drCont = 0; }
else if (st.drEtapa === 2 && dem < P.limite_kw - P.dr_hist_kw) { st.drCont++; if (st.drCont >= 3) { st.drEtapa = 0; st.drCont = 0; } }
if (st.drEtapa < 2) st.drEtapa = forzadas ? 1 : 0;
if (st.drEtapa >= 2) {
    for (const zid of Object.keys(cmds)) {
        if (manual[zid]) continue;
        cmds[zid].luces_nivel = Math.round(cmds[zid].luces_nivel * P.dr_luces * 1000) / 1000;
        cmds[zid].equipos_nivel = Math.min(cmds[zid].equipos_nivel, P.dr_equipos);
    }
}
const drActivo = st.drEtapa > 0;
if (cond("EDIF:DR", drActivo)) alarma("info", "DR_ACTIVO", "EDIF", "Respuesta a la demanda activada");

// ---------------------------------------------------------------- modo seguro
for (const zid of Object.keys(invalidos)) {
    const crit = zonas[zid] && zonas[zid].critica;
    cmds[zid] = Object.assign(cmds[zid] || {}, { hvac_enable: true, hvac_mod: crit ? 1.0 : 0.55, setpoint_c: P.sp_ocupado });
}
for (const zid of Object.keys(zonas)) {
    if (zonas[zid].critica && !invalidos[zid]) cmds[zid] = { hvac_mod: null };
}

// ---------------------------------------------------------------- salidas
const ahora = Date.now();
const salidaCmd = Object.keys(cmds).map(zid => ({
    topic: `${base}/zona/${zid}/cmd`,
    payload: Object.assign({ cmd_id: ++st.cmdId, wall_ms: ahora }, cmds[zid])
}));
const estado = {
    topic: `${base}/ems/estado`,
    payload: {
        ts: med.ts, origen: "nodered", modo: "reglas_dr", dr_activo: drActivo, dr_etapa: st.drEtapa,
        limite_kw: P.limite_kw, n_alarmas: Object.keys(st.activas).length,
        modo_seguro: Object.keys(invalidos), manual: Object.keys(manual), latencia_ms: Date.now() - tInicio, zonas_forzadas: forzadas
    }
};
flow.set("st", st);
const salidaAl = alarmas.map(a => ({ topic: `${base}/alarma`, payload: a }));
return [salidaCmd, estado, salidaAl];

// Nodo función "Cambiar parámetros EMS" — entrada: inject o ems/<edif>/ems/parametros
// payload ej.: {"limite_kw": 135, "sp_ocupado": 24.5}. Permite variar parámetros en vivo (demo).
const actual = flow.get("parametros") || {};
const nuevos = Object.assign({}, actual, msg.payload || {});
flow.set("parametros", nuevos);
node.status({ fill: "green", shape: "dot", text: JSON.stringify(nuevos).slice(0, 60) });
msg.payload = nuevos;
return msg;

// Nodo función "Comando HTTP del panel" — entrada: POST /ems/control (http in)
// Valida el comando del panel de Grafana y lo publica por MQTT.
// Salida 1: override/liberar → ems/<edif>/ems/override; evento simulado → ems/<edif>/sim/control
// Salida 2: parámetros       → ems/<edif>/ems/parametros
// Salida 3: respuesta HTTP (con CORS)
const edif = env.get("EMS_EDIFICIO") || "edificio1";
const base = "ems/" + edif;
const b = (typeof msg.payload === "string" ? JSON.parse(msg.payload || "{}") : msg.payload) || {};
const cors = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
    "Content-Type": "application/json"
};
function responder(code, cuerpo) {
    return { req: msg.req, res: msg.res, statusCode: code, headers: cors, payload: JSON.stringify(cuerpo) };
}
const zonaValida = (z) => /^Z(0[1-9]|10)$/.test(z || "");
if (b.tipo === "override") {
    if (!zonaValida(b.zona) || ["Z09", "Z10"].includes(b.zona)) {
        return [null, null, responder(400, { ok: false, mensaje: `Zona ${b.zona} no admite control manual` })];
    }
    const campos = ["setpoint_c", "hvac_enable", "luces_nivel", "equipos_nivel"].filter((k) => b[k] !== undefined);
    if (!campos.length) return [null, null, responder(400, { ok: false, mensaje: "Sin cambios" })];
    const out = { zona: b.zona, duracion_min: b.duracion_min || 60, usuario: b.usuario || "" };
    for (const k of campos) out[k] = b[k];
    return [{ topic: `${base}/ems/override`, payload: out }, null, responder(200, { ok: true, mensaje: "override publicado", campos })];
}
if (b.tipo === "liberar") {
    if (b.zona !== "*" && !zonaValida(b.zona)) return [null, null, responder(400, { ok: false, mensaje: "Zona inválida" })];
    return [{ topic: `${base}/ems/override`, payload: { tipo: "liberar", zona: b.zona, usuario: b.usuario || "" } }, null, responder(200, { ok: true, mensaje: "liberado" })];
}
if (b.tipo === "parametros") {
    const p = {};
    if (typeof b.limite_kw === "number" && b.limite_kw >= 10 && b.limite_kw <= 100) p.limite_kw = b.limite_kw;
    if (typeof b.sp_ocupado === "number" && b.sp_ocupado >= 20 && b.sp_ocupado <= 28) p.sp_ocupado = b.sp_ocupado;
    if (!Object.keys(p).length) return [null, null, responder(400, { ok: false, mensaje: "Parámetros inválidos" })];
    return [null, { topic: `${base}/ems/parametros`, payload: p }, responder(200, { ok: true, mensaje: "parámetros publicados", parametros: p })];
}
if (b.tipo === "evento") {
    // simulación de fallas y accidentes en el gemelo digital (ems/eventos.py)
    const tipos = ["incendio", "corte_energia", "falla_vrf", "falla_terminal", "puerta_abierta", "sensor",
        "ola_calor", "sobreocupacion", "pico_carga"];
    if (b.accion === "detener") {
        return [{ topic: `${base}/sim/control`, payload: { accion: "evento", operacion: "detener", id: String(b.id || "*") } },
            null, responder(200, { ok: true, mensaje: "evento detenido" })];
    }
    if (!tipos.includes(b.evento)) return [null, null, responder(400, { ok: false, mensaje: `Evento desconocido: ${b.evento}` })];
    if (b.zona !== undefined && !zonaValida(b.zona)) return [null, null, responder(400, { ok: false, mensaje: "Zona inválida" })];
    if (b.unidad !== undefined && !/^VRF-[ABC]$/.test(b.unidad)) return [null, null, responder(400, { ok: false, mensaje: "Unidad inválida" })];
    const dur = Number(b.duracion_min);
    if (!(dur > 0 && dur <= 10080)) return [null, null, responder(400, { ok: false, mensaje: "Duración inválida" })];
    const ev = { accion: "evento", operacion: "iniciar", id: String(b.id || `${b.evento}-${Date.now()}`), evento: b.evento,
        duracion_min: dur, usuario: b.usuario || "" };
    for (const k of ["zona", "unidad", "intensidad"]) if (b[k] !== undefined && b[k] !== null) ev[k] = b[k];
    return [{ topic: `${base}/sim/control`, payload: ev }, null, responder(200, { ok: true, mensaje: "evento publicado", id: ev.id })];
}
return [null, null, responder(400, { ok: false, mensaje: "tipo debe ser override, liberar, parametros o evento" })];

// Nodo función "CORS preflight" — entrada: OPTIONS /ems/control
msg.statusCode = 204;
msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
    "Access-Control-Max-Age": "600"
};
msg.payload = "";
return msg;

// Nodo función "Guardar override del operador" — entrada: ems/<edif>/ems/override
// payload: {zona, setpoint_c?, hvac_enable?, luces_nivel?, equipos_nivel?, duracion_min?, usuario?}
//          {tipo: "liberar", zona: "Z03" | "*"}
// Las zonas críticas (Z09, Z10) no admiten control manual.
const CRITICAS = ["Z09", "Z10"];
const p = msg.payload || {};
const ovs = flow.get("overrides") || {};
const ahora = Date.now();
if (p.tipo === "liberar") {
    if (p.zona === "*") {
        for (const k of Object.keys(ovs)) delete ovs[k];
    } else {
        delete ovs[p.zona];
    }
} else {
    if (!/^Z(0[1-9]|10)$/.test(p.zona || "") || CRITICAS.includes(p.zona)) {
        node.warn(`override rechazado para ${p.zona}`);
        return null;
    }
    const o = { desde: ahora, hasta: ahora + Math.min(Math.max(Number(p.duracion_min) || 60, 1), 1440) * 60000, usuario: p.usuario || "" };
    if (typeof p.setpoint_c === "number") o.setpoint_c = Math.min(Math.max(p.setpoint_c, 20), 28);
    if (typeof p.hvac_enable === "boolean") o.hvac_enable = p.hvac_enable;
    if (typeof p.luces_nivel === "number") o.luces_nivel = Math.min(Math.max(p.luces_nivel, 0), 1);
    if (typeof p.equipos_nivel === "number") o.equipos_nivel = Math.min(Math.max(p.equipos_nivel, 0), 1);
    ovs[p.zona] = o;
}
flow.set("overrides", ovs);
node.status({ fill: Object.keys(ovs).length ? "yellow" : "green", shape: "dot", text: `manual: ${Object.keys(ovs).join(", ") || "ninguna"}` });
msg.payload = ovs;
return msg;
